// openSeededStore opens a fresh temp store for a test.
func openSeededStore(t *testing.T) *store.Store {
	t.Helper()
	db, err := store.OpenWithContext(context.Background(), filepath.Join(t.TempDir(), "data.db"))
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	t.Cleanup(func() { _ = db.Close() })
	return db
}

func TestAuditGrants(t *testing.T) {
	db := openSeededStore(t)
	sdb := db.DB()

	// Members.
	mustExec(t, sdb, `INSERT INTO members(id, data, member_id, email) VALUES (?,?,?,?)`,
		"m1", `{}`, "m1", "alice@acme.com")
	mustExec(t, sdb, `INSERT INTO members(id, data, member_id, email) VALUES (?,?,?,?)`,
		"m2", `{}`, "m2", "bob@acme.com")
	mustExec(t, sdb, `INSERT INTO members(id, data, member_id, email) VALUES (?,?,?,?)`,
		"m3", `{}`, "m3", "carol@acme.com")
	// Team t1 with members m2, m3.
	mustExec(t, sdb, `INSERT INTO teams(id, data, team_id, name) VALUES (?,?,?,?)`,
		"t1", `{}`, "t1", "Analysts")
	mustExec(t, sdb, `INSERT INTO teams_members(id, teams_id, data, parent_id) VALUES (?,?,?,?)`,
		"tm1", "t1", `{"memberId":"m2","email":"bob@acme.com"}`, "t1")
	mustExec(t, sdb, `INSERT INTO teams_members(id, teams_id, data, parent_id) VALUES (?,?,?,?)`,
		"tm2", "t1", `{"memberId":"m3","email":"carol@acme.com"}`, "t1")
	// Workbook wb1: a direct member grant (m1) + a team grant (t1).
	mustExec(t, sdb, `INSERT INTO grants(id, data, inode_id, inode_type, member_id, permission) VALUES (?,?,?,?,?,?)`,
		"g1", `{}`, "wb1", "workbook", "m1", "edit")
	mustExec(t, sdb, `INSERT INTO grants(id, data, inode_id, inode_type, team_id, permission) VALUES (?,?,?,?,?,?)`,
		"g2", `{}`, "wb1", "workbook", "t1", "view")

	rows, err := auditGrants(sdb, "wb1")
	if err != nil {
		t.Fatalf("auditGrants: %v", err)
	}

	got := map[string]string{} // email -> grantedVia
	for _, r := range rows {
		got[r.Email] = r.GrantedVia
	}
	want := map[string]string{
		"alice@acme.com": "direct",
		"bob@acme.com":   "team:Analysts",
		"carol@acme.com": "team:Analysts",
	}
	if len(got) != len(want) {
		t.Fatalf("expected %d effective members, got %d: %+v", len(want), len(got), rows)
	}
	for email, via := range want {
		if got[email] != via {
			t.Errorf("%s: grantedVia = %q, want %q", email, got[email], via)
		}
	}

	// Empty grants -> empty slice, not error.
	empty, err := auditGrants(sdb, "does-not-exist")
	if err != nil {
		t.Fatalf("auditGrants(empty): %v", err)
	}
	if len(empty) != 0 {
		t.Errorf("expected no rows for unknown resource, got %d", len(empty))
	}
}

func TestGrantIsOrgWide(t *testing.T) {
	cases := []struct {
		name       string
		raw        string
		permission string
		want       bool
	}{
		{"plain member grant", `{}`, "edit", false},
		{"public permission keyword", `{}`, "publicView", true},
		{"public flag in data", `{"isPublic":true}`, "view", true},
		{"org scope in data", `{"scope":"organization"}`, "view", true},
		{"nothing", `{"foo":"bar"}`, "view", false},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			if got := grantIsOrgWide([]byte(tc.raw), tc.permission); got != tc.want {
				t.Errorf("grantIsOrgWide(%q,%q) = %v, want %v", tc.raw, tc.permission, got, tc.want)
			}
		})
	}
}
